25	
26	// Inner component that initializes contexts
27	function AppInitializer({ children }: { children: React.ReactNode }) {
28	  const { isInitialized: authInitialized, initialize: initAuth, currentUser } = useAuth();
29	  const { isInitialized: instanceInitialized, initialize: initInstance } = useInstance();
30	  const initStartedRef = useRef(false);
31	
32	  // Initialize on mount - run in parallel for better performance
33	  useEffect(() => {
34	    if (initStartedRef.current) return;
35	    initStartedRef.current = true;
36	
37	    const init = async () => {
38	      await Promise.all([initInstance(), initAuth()]);
39	    };
40	    init();
41	  }, [initAuth, initInstance]);
42	
43	  // Proactively refresh token on window focus to prevent 401 errors
44	  // Only enabled when user is authenticated
45	  // Related: https://github.com/usememos/memos/issues/5589
46	  useTokenRefreshOnFocus(refreshAccessToken, !!currentUser);
47	
48	  // Live refresh: listen for memo changes via SSE and invalidate caches.
49	  useLiveMemoRefresh();
50	
51	  if (!authInitialized || !instanceInitialized) {
52	    return null;
53	  }
54	
55	  return <>{children}</>;
56	}
57	
58	function Main() {
59	  return (
60	    <ErrorBoundary>
61	      <QueryClientProvider client={queryClient}>
62	        <InstanceProvider>
63	          <AuthProvider>
64	            <ViewProvider>
65	              <AppInitializer>
66	                <RouterProvider router={router} />
67	                <Toaster position="top-right" />
68	              </AppInitializer>
69	            </ViewProvider>
70	          </AuthProvider>
71	        </InstanceProvider>
72	        <ReactQueryDevtools initialIsOpen={false} />
73	      </QueryClientProvider>
74	    </ErrorBoundary>
75	  );
76	}
77	
78	const container = document.getElementById("root");
79	const root = createRoot(container as HTMLElement);
80	root.render(<Main />);
